import threading, http.server, socketserver, functools, json, os, shutil
from playwright.sync_api import sync_playwright
ROOT=os.path.abspath(os.path.join(os.path.dirname(__file__),'..','..'))
class Quiet(http.server.SimpleHTTPRequestHandler):
    def log_message(self,*a): pass
server=socketserver.ThreadingTCPServer(('127.0.0.1',0),functools.partial(Quiet,directory=ROOT));server.daemon_threads=True
threading.Thread(target=server.serve_forever,daemon=True).start()
url='http://127.0.0.1:%d/index.html'%server.server_address[1]
checks=[]; errors=[]
def ck(name,ok):
    checks.append((name,bool(ok))); print(('PASS ' if ok else 'FAIL ')+name)
with sync_playwright() as p:
    browser=p.chromium.launch(executable_path=shutil.which('google-chrome') or shutil.which('chromium'),headless=True,args=['--no-sandbox','--disable-gpu'])
    page=browser.new_page(viewport={'width':1440,'height':900})
    page.on('pageerror',lambda e:errors.append(str(e)))
    page.add_init_script("try{Object.defineProperty(window,'localStorage',{value:{getItem:()=>null,setItem:()=>{},removeItem:()=>{},clear:()=>{},key:()=>null,get length(){return 0}},configurable:true});Object.defineProperty(window,'sessionStorage',{value:{getItem:()=>null,setItem:()=>{},removeItem:()=>{},clear:()=>{},key:()=>null,get length(){return 0}},configurable:true});}catch(e){}")
    page.goto(url,wait_until='domcontentloaded',timeout=120000)
    page.wait_for_function("!!window.CVEditorShellP231 && !!window.CVPosterShellP232 && !!document.querySelector('#page-poster')",timeout=90000)
    page.evaluate("CV.go('poster')")
    page.wait_for_function("!!document.querySelector('#cv231-shell-poster') && CVEditorShellP231.state('poster').enabled",timeout=30000)
    for name,vp in [('1440x900',{'width':1440,'height':900}),('1280x720',{'width':1280,'height':720})]:
        page.set_viewport_size(vp);page.wait_for_timeout(500)
        d=page.evaluate("""()=>{const p=document.querySelector('#page-poster'),s=document.querySelector('#cv231-shell-poster'),w=document.querySelector('#canvasWrap'),stage=document.querySelector('#stage'),r=s.getBoundingClientRect();return {active:p.classList.contains('active'),enabled:p.classList.contains('cv231-enabled'),height:r.height,width:r.width,pageScroll:document.scrollingElement.scrollHeight,innerHeight,toolbar:!!document.querySelector('#cv231-shell-poster .toolbar'),canvas:!!w&&w.getBoundingClientRect().width>200&&w.getBoundingClientRect().height>200,stage:!!stage&&stage.getBoundingClientRect().width>60,undo:!!document.querySelector('[data-cv231-action=undo]'),redo:!!document.querySelector('[data-cv231-action=redo]'),save:!!document.querySelector('[data-cv231-action=save]'),exports:[...document.querySelectorAll('#cv231-shell-poster .headActions button')].map(x=>x.textContent.trim())}}""")
        ck(name+' shell and native regions are mounted',d['active'] and d['enabled'] and d['toolbar'] and d['canvas'] and d['stage'])
        ck(name+' page does not require vertical scrolling',d['pageScroll']<=d['innerHeight']+4)
        ck(name+' Undo/Redo/Save and native exports remain present',d['undo'] and d['redo'] and d['save'] and any('PNG' in x for x in d['exports']) and any('SVG' in x for x in d['exports']))
    page.set_viewport_size({'width':1440,'height':900});page.wait_for_timeout(300)
    before=page.evaluate('CV.poster.doc.layers.length')
    page.locator('#cv231-shell-poster .toolbar button').filter(has_text='Chữ').first.click()
    page.wait_for_function('(n)=>CV.poster.doc.layers.length===n+1',arg=before,timeout=10000)
    after=page.evaluate('CV.poster.doc.layers.length')
    page.locator('[data-cv231-action="undo"]').click();page.wait_for_function('(n)=>CV.poster.doc.layers.length===n',arg=before,timeout=10000)
    ck('Poster add + native Undo restores exact prior layer count',after==before+1 and page.evaluate('CV.poster.doc.layers.length')==before)
    page.locator('[data-cv231-action="redo"]').click();page.wait_for_function('(n)=>CV.poster.doc.layers.length===n+1',arg=before,timeout=10000)
    ck('Poster native Redo restores the added layer',page.evaluate('CV.poster.doc.layers.length')==before+1)
    legacy_action=page.locator('#cv231-shell-poster [data-cv231-action="legacy"]')
    ck('Legacy Layout action is uniquely scoped to Poster shell',legacy_action.count()==1)
    legacy_action.click();page.wait_for_timeout(250)
    legacy=page.evaluate("""()=>({off:!CVEditorShellP231.state('poster').enabled,head:getComputedStyle(document.querySelector('#page-poster>.head')).display!=='none',toolbar:document.querySelector('#page-poster .toolbar')?.closest('.editor')!==null,canvas:document.querySelector('#page-poster #canvasWrap')?.closest('.editor')!==null})""")
    ck('Legacy Layout restores original DOM positions and header',legacy['off'] and legacy['head'] and legacy['toolbar'] and legacy['canvas'])
    page.locator('#page-poster [data-cv231-launch]').click();page.wait_for_function("CVEditorShellP231.state('poster').enabled",timeout=10000)
    ck('Launch Editor re-enters shell without duplicate IDs',page.locator('#cv231-shell-poster').count()==1 and page.locator('#page-poster [data-cv231-launch]').count()==1)
    page.evaluate("window.__p232SaveCalls=[];const original=CV.project.save;CV.project.save=function(v){window.__p232SaveCalls.push(v);return original.call(CV.project,v)}")
    page.locator('[data-cv231-action="save"]').click();page.wait_for_function('window.__p232SaveCalls.length>=1',timeout=10000)
    ck('Manual Save delegates to canonical Project.save(true)',page.evaluate('window.__p232SaveCalls.includes(true)'))
    page.evaluate("CV.go('home')")
    page.wait_for_function("!document.querySelector('#page-poster').classList.contains('active')",timeout=10000)
    page.wait_for_function("!document.querySelector('.app').classList.contains('cv231-app-active') && !document.querySelector('.main').classList.contains('cv231-app-active')",timeout=10000)
    ck('Navigating away releases editor app height/overflow lock',not page.locator('.app').evaluate("e=>e.classList.contains('cv231-app-active')") and not page.locator('.main').evaluate("e=>e.classList.contains('cv231-app-active')"))
    page.evaluate("CV.go('poster')")
    page.wait_for_function("document.querySelector('#page-poster').classList.contains('active') && document.querySelector('.app').classList.contains('cv231-app-active')",timeout=10000)
    ck('Returning to Poster restores editor app lock',page.locator('.app').evaluate("e=>e.classList.contains('cv231-app-active')"))
    page.set_viewport_size({'width':390,'height':844});page.wait_for_timeout(500)
    mobile=page.evaluate("""()=>({width:document.documentElement.scrollWidth,innerWidth,canvas:document.querySelector('#cv231-shell-poster #canvasWrap').getBoundingClientRect().width,rail:document.querySelector('#cv231-shell-poster .cv231-rail').getBoundingClientRect().height})""")
    ck('390px mobile layout has no horizontal overflow and retains canvas',mobile['width']<=mobile['innerWidth']+1 and mobile['canvas']>180 and mobile['rail']>=40)
    toggle_props=page.locator('#cv231-shell-poster [data-cv231-action="toggle-props"]')
    ck('Poster properties action is uniquely scoped to Poster shell',toggle_props.count()==1)
    toggle_props.click();page.wait_for_timeout(150)
    ck('Mobile property drawer opens on explicit user action',page.locator('#cv231-shell-poster').evaluate("e=>e.classList.contains('cv231-mobile-props-open')"))
    ck('No uncaught JavaScript page errors',len(errors)==0)
    if errors: print('PAGE_ERRORS '+json.dumps(errors,ensure_ascii=False))
    browser.close()
    server.shutdown();server.server_close()
failed=[n for n,v in checks if not v]
print('%d/%d P231/P232 browser assertions passed'%(len(checks)-len(failed),len(checks)))
if failed: raise SystemExit('Failures: '+', '.join(failed))
if errors: raise SystemExit('Uncaught page errors: '+repr(errors))